css:
/* @prim:begin 52-plan-matrix */
.pm { display: flex; flex-direction: column; gap: 12px; }
.pm > * { margin: 0; }
.pm-src, .pm-note { font-size: var(--fs-body); line-height: 1.55; color: var(--text-secondary); }
.pm-table { width: 100%; border-collapse: collapse; font-size: var(--fs-body); }
.pm-table th { text-align: left; font-size: var(--fs-body); font-weight: 600; color: var(--text-secondary); padding: 0 12px 8px; border-bottom: 1px solid var(--border); white-space: nowrap; }
.pm-table td { text-align: left; vertical-align: top; padding: 12px; line-height: 1.5; color: var(--text); border-bottom: 1px solid var(--border); }
.pm-table td:first-child { font-weight: 600; width: 28%; }
.pm-table tr:last-child td { border-bottom: 0; }
.pm-khead { font-size: var(--fs-body); font-weight: 600; line-height: 1.4; color: var(--text); margin-top: 4px; }
.pm-know { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 12px; }
.pm-k { border: 1px solid var(--border); border-radius: var(--ds-r-sm); background: var(--surface); padding: 12px 14px; }
.pm-k p { margin: 0; font-size: var(--fs-body); line-height: 1.5; color: var(--text); }
.pm-k .pm-kl { font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--cyan); margin-bottom: 4px; }
@media (max-width: 599px) { .pm-table thead { display: none; } .pm-table tr { display: block; padding: 12px 0; border-bottom: 1px solid var(--border); } .pm-table tr:last-child { border-bottom: 0; } .pm-table td { display: block; width: auto; padding: 2px 0; border: 0; } .pm-table td:first-child { width: auto; margin-bottom: 4px; } .pm-table td[data-label]:not(:first-child)::before { content: attr(data-label); display: block; font-size: var(--fs-label); font-weight: 600; color: var(--text-secondary); } }
/* @prim:end 52-plan-matrix */
[data-stage], [data-state] { overflow-x: auto; }

demo:
function pm(h,rows,know){var w=document.createElement('div');w.className='pm';var t='<p class="pm-src">Rows paraphrase the duties on the role page. Every cell is a proposal to edit.</p><table class="pm-table"><thead><tr><th>Your page asks me to</th>'+h.map(function(d){return '<th>By day '+d+'</th>'}).join('')+'</tr></thead><tbody>'+rows.map(function(r){return '<tr>'+r.map(function(c,i){return '<td'+(i?' data-label="By day '+h[i-1]+'"':'')+'>'+c+'</td>'}).join('')+'</tr>'}).join('')+'</tbody></table><p class="pm-khead">How you would know it is working</p><div class="pm-know">'+know.map(function(k,i){return '<div class="pm-k"><p class="pm-kl">Day '+h[i]+'</p><p>'+k+'</p></div>'}).join('')+'</div>';w.innerHTML=t;return w}
var R=[['Generate and validate ideas','30 theses, kill criteria first','5 one-pagers','A steady weekly flow'],['Pitch the committee','A hatch chosen','A hatch pitched','A second pitched']];
var K=['Theses you have read.','A hatch in front of the committee.','A founder signed.'];
document.querySelector('[data-stage]').appendChild(pm([30,90,180],R,K));
document.querySelectorAll('[data-state]').forEach(function(el,i){var a=STATES[i];el.appendChild(pm(a[0],R.slice(0,a[1]),K))});
